const SB_AJUDA = "Squad BRA - Upstream · ponte em um arquivo (squad-bra-2arquivos/1)\n\n  node squad-bra-ponte.mjs                    sobe a ponte (precisa do squad-bra-app.html na mesma pasta)\n  node squad-bra-ponte.mjs --extrair <pasta>  reconstrói o repositório completo (lê também o squad-bra-app.html)\n        [--app <arquivo.html>] [--forcar]\n  node squad-bra-ponte.mjs --verificar        confere o sha256 de todos os arquivos embutidos\n  node squad-bra-ponte.mjs --listar           lista os arquivos embutidos na ponte\n  node squad-bra-ponte.mjs --ajuda            esta ajuda\n\nOpcional: copilot-runtime-<plataforma>.tgz na mesma pasta = GitHub Copilot (sem ele, agente simulado).\nConfiguração: .env na mesma pasta (criado do exemplo na primeira vez). Dados: .dados/ na mesma pasta.";
const ARQUIVOS = [];
function arq(caminho, meta, conteudo) { ARQUIVOS.push({ caminho, meta, conteudo }); }

//@@ARQUIVO .env.exemplo | bytes=2786 | sha256=9a60199e4742cb984face3c9324915a08d42b218e74811730d1ab0db61544eeb | papel=execucao | codificacao=texto
arq(".env.exemplo", {"papel":"execucao","codificacao":"texto","bytes":2786,"sha256":"9a60199e4742cb984face3c9324915a08d42b218e74811730d1ab0db61544eeb"}, String.raw`# Ponte local do DIF — copie para .env (nunca versione o .env) ou defina no ambiente.

# Endereço da ponte (só loopback é aceito)
DIF_PONTE_PORTA=4317
# DIF_PONTE_HOST=127.0.0.1

# GitHub: github.com, <empresa>.ghe.com ou https://ghes.empresa (GHES)
DIF_GITHUB_HOST=github.com
# Login: sso (padrão) = o runtime do Copilot abre a página de login do GitHub numa aba do navegador.
# NÃO precisa de client id nem de segredo. Exige o runtime do Copilot (nível 3 / .tgz do kit).
DIF_GITHUB_LOGIN=sso
# Tempo máximo para concluir o login na aba (ms)
# DIF_SSO_TEMPO_MS=600000

# --- Modo legado (só se DIF_GITHUB_LOGIN=oauth-app): app de OAuth próprio ---
# DIF_GITHUB_CLIENT_ID=
# DIF_GITHUB_FLUXO=device
# DIF_GITHUB_CLIENT_SECRET=
# DIF_GITHUB_ESCOPOS=read:user repo
# Reaproveitar login existente (COPILOT_GITHUB_TOKEN, GH_TOKEN, GITHUB_TOKEN ou ⟦CRASE⟧gh auth token⟦CRASE⟧)
# DIF_GITHUB_USAR_LOGIN_EXISTENTE=1
# memoria (padrão) ou arquivo (~/.dif-ponte/sessao.json com permissão 0600)
# DIF_PONTE_PERSISTIR=memoria

# Banco de dados (descobertas, conversas, backlogs, pessoas e auditoria)
# sqlite (padrão; módulo nativo do Node, arquivo único) | postgres (futuro — ver docs/DADOS.md)
DIF_BD=sqlite
# Arquivo do banco (padrão: <pasta de dados>/dif.db). Backup = copiar este arquivo com a ponte parada.
# DIF_BD_ARQUIVO=
# Postgres (futuro): DIF_BD_URL=postgres://usuario@servidor:5432/dif  (senha por variável/cofre, nunca no repositório)
# DIF_BD_URL=

# Contas: aberto (qualquer um cria conta; padrão na POC local) | admin (só administradores criam contas)
# O primeiro cadastro vira administrador.
DIF_CADASTRO=aberto
# Primeiro acesso com o banco vazio: (vazio) = pergunta (importar deste navegador, demonstração ou base zerada)
# demo = começa direto com a demonstração fictícia | zerada = começa com a base zerada
# DIF_PRIMEIRO_ACESSO=
# Fonte "Upstream": os .zip enviados são descompactados em <pasta de dados>/external-sources/<fonte> (o .zip é descartado).
# Servidores MCP cadastrados como fonte usam ⟦DOLAR_CHAVE⟧env:NOME} para segredos: defina aqui as variáveis que eles citam, ex.:
# MCP_GARANTIAS_TOKEN=
# Sessão: minutos sem uso até expirar e duração máxima em dias
# DIF_SESSAO_INATIVIDADE_MIN=720
# DIF_SESSAO_MAXIMO_DIAS=7

# Agentes
# auto (Copilot depois de ativado em Configurações › Ativar Copilot; antes disso, agente simulado) | copilot (sempre) | falso (sempre)
DIF_PROVEDOR=auto
# Pasta com os seus *.agent.md
DIF_AGENTES_DIR=
# DIF_COPILOT_MODELO=
# DIF_COPILOT_USAR_LOGIN_CLI=1
# DIF_CHAT_TEMPO_LIMITE_MS=300000

# BYOK (sem assinatura Copilot): openai | azure | anthropic
# DIF_BYOK_TIPO=
# DIF_BYOK_BASE_URL=
# DIF_BYOK_CHAVE=
# DIF_BYOK_MODELO=

# Exportar backlog como issues no GitHub (desligado por padrão)
# DIF_EXPORTAR_ISSUES=0
`);
//@@FIM .env.exemplo

//@@ARQUIVO .gitignore | bytes=115 | sha256=2e1b8f159a393b1e2d4b851aa2f3c0190b0efb775bc4fd4d01e08d67d9ee5eb8 | papel=repositorio | codificacao=texto
