      const f = fontes ? porId.get(e.fonteId) || porNome.get(sem(e.fonteNome)) : null;
      if (fontes && !f) continue;
      evidencias.push({ fonteId: f ? f.id : txt(e.fonteId, 40), fonteNome: f ? f.nome : txt(e.fonteNome, 120), tipo: f ? f.tipo : txt(e.tipo, 30) || 'documento',
        arquivo: txt(e.arquivo, 240), linha: txt(e.linha, 60), trecho: txt(e.trecho, 400) });
