//@@ARQUIVO ponte/src/agentes/carregador.mjs | bytes=2340 | sha256=a00f247f3f8b09791dcbf3d84f531ad3b77602a8a2de5fbc560cb9c618102687 | papel=execucao | codificacao=texto
arq("ponte/src/agentes/carregador.mjs", {"papel":"execucao","codificacao":"texto","bytes":2340,"sha256":"a00f247f3f8b09791dcbf3d84f531ad3b77602a8a2de5fbc560cb9c618102687"}, String.raw`// Carrega definições *.agent.md: padrão (exemplos) < pasta local do usuário < repositórios GitHub.
// O mesmo ⟦CRASE⟧name⟦CRASE⟧ em uma origem posterior substitui o anterior.
import { readdirSync, readFileSync, existsSync, statSync } from 'node:fs';
import { join, basename } from 'node:path';
import { parse } from 'yaml';

/** Separa front matter YAML e corpo. */
export function lerAgente(texto, arquivo) {
  const m = String(texto).replace(/^﻿/, '').match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
  if (!m) throw new Error('sem front matter (--- … ---)');
  const fm = parse(m[1]) || {};
  const nome = String(fm.name || basename(arquivo).replace(/\.agent\.md$/, '')).trim();
  if (!/^[a-z0-9][a-z0-9._-]{0,63}$/i.test(nome)) throw new Error(⟦CRASE⟧nome inválido "⟦DOLAR_CHAVE⟧nome}"⟦CRASE⟧);
  const prompt = m[2].trim();
  if (!prompt) throw new Error('corpo (prompt) vazio');
  const tools = Array.isArray(fm.tools) ? fm.tools.map(String) : null;
  return { nome, titulo: String(fm.displayName || fm.title || nome), descricao: String(fm.description || ''), prompt, tools, modelo: fm.model ? String(fm.model) : null };
}

function lerPasta(dir, origem, desligados = []) {
  const agentes = [], avisos = [];
  if (!dir || !existsSync(dir)) return { agentes, avisos };
  for (const n of readdirSync(dir).sort()) {
    const p = join(dir, n);
    if (statSync(p).isDirectory() || !n.endsWith('.agent.md') || desligados.includes(n.replace(/\.agent\.md$/, ''))) continue;
    try { agentes.push({ ...lerAgente(readFileSync(p, 'utf8'), n), origem, arquivo: p }); }
    catch (e) { avisos.push(⟦CRASE⟧⟦DOLAR_CHAVE⟧n}: ⟦DOLAR_CHAVE⟧e.message}⟦CRASE⟧); }
  }
  return { agentes, avisos };
}

export function carregarAgentes({ dirPadrao, dirLocal, dirCacheRepos, pacotes = [] }) {
  const mapa = new Map(), avisos = [];
  const juntar = r => { r.agentes.forEach(a => mapa.set(a.nome, a)); avisos.push(...r.avisos); };
  juntar(lerPasta(dirPadrao, 'padrao'));
  juntar(lerPasta(dirLocal, 'local'));
  if (dirCacheRepos && existsSync(dirCacheRepos)) {
    for (const sub of readdirSync(dirCacheRepos).sort()) juntar(lerPasta(join(dirCacheRepos, sub), 'repo'));
  }
  // pacotes importados (Configurações do chat) por último: ligados substituem agentes de mesmo nome
  for (const p of pacotes) juntar(lerPasta(p.dir, p.origem, p.desligados));
  return { agentes: [...mapa.values()], avisos };
}
`);
//@@FIM ponte/src/agentes/carregador.mjs

//@@ARQUIVO ponte/src/agentes/copilot.mjs | bytes=13972 | sha256=c622cd68358a27e706e1b561156d82ccf20b316440ca9dea0b1bc30005570a18 | papel=execucao | codificacao=texto
