/** Traduz falhas do SDK/runtime para os códigos dif-chat/1. */
export function classificarErro(e) {
  const m = String((e && (e.message || e.errorType)) || e || '').toLowerCase();
  const tipo = String((e && (e.errorType || e.code)) || '').toLowerCase();
  if (/enoent|spawn|not found.*(cli|runtime)|runtime.*(not found|missing)|cannot find (module|package)/.test(m) || tipo === 'enoent') return 'CLI_AUSENTE';
  if (/(no|not|without).*(copilot).*(access|subscription|seat|license|enabled)|copilot.*(not enabled|subscription)|quota|403|forbidden/.test(m + ' ' + tipo)) return 'SEM_COPILOT';
  if (/401|unauthori[sz]ed|bad credentials|not (logged|authenticated)|authentication/.test(m + ' ' + tipo)) return 'SEM_LOGIN';
  if (/timeout|timed out/.test(m)) return 'TEMPO_ESGOTADO';
  return 'INTERNO';
}

