arq("ponte/src/agentes/permissoes.mjs", {"papel":"execucao","codificacao":"texto","bytes":2701,"sha256":"7b3dc3485f09c97958322033899fc83810d0af97c0095459fff2e70339a804d3"}, String.raw`// Política de permissões do agente: só LEITURA dentro do workspace da conversa. O resto é negado e auditado.
import { resolve, relative, isAbsolute, sep } from 'node:path';
import { realpathSync, existsSync } from 'node:fs';
import { ferramentaLiberada } from '../../../compartilhado/fonte-mcp.mjs';

const real = p => { try { return existsSync(p) ? realpathSync(p) : resolve(p); } catch { return resolve(p); } };

export function dentroDe(dir, caminho) {
  if (typeof caminho !== 'string' || !caminho) return false;
  const base = real(dir);
  const alvo = real(isAbsolute(caminho) ? caminho : resolve(base, caminho));
  const rel = relative(base, alvo);
  return rel === '' || (!rel.startsWith('..') && !isAbsolute(rel) && !rel.split(sep).includes('..'));
}

/**
 * @param {object} [extra] levantamento via chat: pastasLeitura (fontes Upstream selecionadas) e mcp (servidor → ferramentas liberadas)
 * @returns {{ decisao: 'aprovada'|'negada', motivo: string, acao: string }}
 */
export function decidirPermissao(pedido, dirWorkspace, extra = {}) {
  const tipo = pedido && pedido.kind;
  if (tipo === 'read') {
    const caminho = pedido.resolvedPath || pedido.path;
    if (dentroDe(dirWorkspace, caminho)) return { decisao: 'aprovada', motivo: 'leitura dentro do workspace da conversa', acao: ⟦CRASE⟧ler ⟦DOLAR_CHAVE⟧String(pedido.path).split(/[\\/]/).pop()}⟦CRASE⟧ };
    if ((extra.pastasLeitura || []).some(p => dentroDe(p, caminho))) return { decisao: 'aprovada', motivo: 'leitura de uma fonte Upstream selecionada', acao: ⟦CRASE⟧ler ⟦DOLAR_CHAVE⟧String(pedido.path).split(/[\\/]/).pop()}⟦CRASE⟧ };
    return { decisao: 'negada', motivo: 'leitura fora do workspace da conversa', acao: 'ler arquivo externo' };
  }
  if (tipo === 'mcp' && extra.mcp) {
    const lista = Object.hasOwn(extra.mcp, pedido.serverName) ? extra.mcp[pedido.serverName] : null;
    const acao = ⟦CRASE⟧MCP ⟦DOLAR_CHAVE⟧pedido.serverName || '?'} · ⟦DOLAR_CHAVE⟧pedido.toolName || '?'}⟦CRASE⟧;
    if (!lista) return { decisao: 'negada', motivo: 'servidor MCP não selecionado nas fontes', acao };
    if (ferramentaLiberada(pedido.toolName, lista) || pedido.readOnly === true) return { decisao: 'aprovada', motivo: pedido.readOnly === true && !ferramentaLiberada(pedido.toolName, lista) ? 'ferramenta MCP de leitura' : 'ferramenta MCP liberada na fonte', acao };
    return { decisao: 'negada', motivo: 'ferramenta MCP não liberada na fonte', acao };
  }
  const nomes = { shell: 'executar comando', write: 'gravar arquivo', url: 'acessar URL', mcp: 'chamar servidor MCP', memory: 'gravar memória', 'custom-tool': 'ferramenta personalizada' };
  return { decisao: 'negada', motivo: 'a ponte só permite leitura do contexto', acao: nomes[tipo] || ⟦CRASE⟧ação "⟦DOLAR_CHAVE⟧tipo || 'desconhecida'}"⟦CRASE⟧ };
}
`);
