//@@ARQUIVO ponte/src/agentes/provedor.mjs | bytes=4479 | sha256=3a58d11917ea4c7852e5a990bfd53c98ce08c15e8ac700151f752966c6ff1256 | papel=execucao | codificacao=texto
arq("ponte/src/agentes/provedor.mjs", {"papel":"execucao","codificacao":"texto","bytes":4479,"sha256":"3a58d11917ea4c7852e5a990bfd53c98ce08c15e8ac700151f752966c6ff1256"}, String.raw`// Contrato dos provedores de agentes e o que é comum a todos (instrução do turno e fechamento com validação).
//
// interface ProvedorAgente:
//   nome: 'copilot' | 'falso'
//   disponivel(): Promise<{ ok: boolean, motivo?: string }>
//   executar(turno: Turno): Promise<string>   // emite eventos dif-chat/1 e devolve o texto final
//   encerrar(): Promise<void>
//
/** @typedef {{ conversa:string, agente:object, agentes:object[], mensagens:{papel:'usuario'|'assistente', texto:string}[], contexto:object,
 *              workspace:{dir:string, fatos:number, bytes:number}, novoContexto:boolean, sinal:AbortSignal, emitir:(evento:string, dados:object)=>void }} Turno */
import { resumoMarkdown } from './workspace.mjs';
import { extrairBacklog } from '../../../compartilhado/extrair-backlog.mjs';
import { validarBacklog } from '../../../compartilhado/backlog-schema.mjs';

export const REGRAS_SAIDA = [
  'Use SOMENTE os fatos do contexto (ids FN-…). Nunca invente regra, valor ou fato.',
  'Termine a resposta com UM bloco ⟦CRASE⟧⟦CRASE⟧⟦CRASE⟧dif-backlog⟦CRASE⟧⟦CRASE⟧⟦CRASE⟧ contendo JSON no esquema dif-backlog/1:',
  '{"esquema":"dif-backlog/1","descoberta":"<id>","pacote_versao":<n>,"agente":"<nome>","gerado_em":"<ISO>",',
  ' "epicos":[{"id":"EP-01","titulo":"","objetivo":"","valor_negocio":"","escopo":[],"fora_escopo":[],"fatos":["FN-…"],"riscos":[],',
  '   "historias":[{"id":"HI-01.1","titulo":"","como":"","quero":"","para":"","criterios":[{"id":"CA-1","gherkin":"Dado … Quando … Então …","fatos":["FN-…"]}],',
  '     "fatos":["FN-…"],"dependencias":[],"perguntas_abertas":[],"tamanho":"P|M|G"}]}],',
  ' "lacunas":[{"descricao":"","fatos":["FN-…"]}]}',
  'Toda história e todo critério citam ao menos um fato. Dúvidas vão em perguntas_abertas ou lacunas.',
  'Se o pedido não for gerar backlog (ex.: uma pergunta), responda em texto e só inclua o bloco se ele mudar.',
].join('\n');

/** Mensagem enviada ao agente no turno. O contexto completo vai para o workspace; o resumo entra no prompt se couber. */
export function montarPrompt(turno, { maxFatosNoPrompt = 400 } = {}) {
  const ctx = turno.contexto, ult = turno.mensagens[turno.mensagens.length - 1];
  const partes = [];
  if (turno.novoContexto) {
    partes.push(⟦CRASE⟧[Contexto DIF] ⟦DOLAR_CHAVE⟧ctx.descoberta.nome} (⟦DOLAR_CHAVE⟧ctx.descoberta.id}) · cluster ⟦DOLAR_CHAVE⟧ctx.descoberta.cluster} · pacote v⟦DOLAR_CHAVE⟧ctx.versao.n} · ⟦DOLAR_CHAVE⟧turno.workspace.fatos} fatos.⟦CRASE⟧);
    partes.push('Os fatos completos estão em contexto.md e contexto.json na pasta de trabalho atual. Leia-os antes de responder.');
    if (turno.workspace.fatos <= maxFatosNoPrompt) partes.push('', resumoMarkdown(ctx, { maxFatos: maxFatosNoPrompt }));
    partes.push('', '[Regras de saída]', REGRAS_SAIDA);
    // sessão nova com histórico vindo do navegador (ex.: ponte reiniciada)
    const anteriores = turno.mensagens.slice(0, -1);
    if (anteriores.length) partes.push('', '[Conversa anterior]', ...anteriores.map(m => ⟦CRASE⟧⟦DOLAR_CHAVE⟧m.papel === 'usuario' ? 'Usuário' : 'Assistente'}: ⟦DOLAR_CHAVE⟧m.texto}⟦CRASE⟧));
  } else partes.push(⟦CRASE⟧[Lembrete] Mesmo contexto (v⟦DOLAR_CHAVE⟧ctx.versao.n}). Mantenha o formato dif-backlog/1 se devolver backlog.⟦CRASE⟧);
  partes.push('', '[Pedido]', ult.texto);
  return partes.join('\n');
}

/** Ao fim do turno: procura o bloco dif-backlog, valida contra o pacote e emite o evento ⟦CRASE⟧backlog⟦CRASE⟧. */
export function fecharTurno(texto, turno) {
  const x = extrairBacklog(texto);
  if (x.backlog) {
    const validacao = validarBacklog(x.backlog, turno.contexto);
    turno.emitir('backlog', { backlog: x.backlog, validacao });
    return validacao;
  }
  if (x.erroDeParse) { const validacao = { ok: false, erros: [x.erroDeParse], avisos: [], cobertura: 0, cobertos: 0, total: 0, naoCobertos: [], totais: {} }; turno.emitir('backlog', { backlog: null, validacao }); return validacao; }
  return null;
}

/** Corta um texto em pedaços "naturais" para simular streaming. */
export function pedacos(texto, tam = 28) {
  const out = []; let atual = '';
  for (const p of texto.split(/(\s+)/)) { atual += p; if (atual.length >= tam) { out.push(atual); atual = ''; } }
  if (atual) out.push(atual);
  return out;
}

export const espera = (ms, sinal) => new Promise((ok, erro) => {
  if (sinal && sinal.aborted) return erro(Object.assign(new Error('cancelado'), { name: 'AbortError' }));
  const t = setTimeout(ok, ms);
  sinal && sinal.addEventListener('abort', () => { clearTimeout(t); erro(Object.assign(new Error('cancelado'), { name: 'AbortError' })); }, { once: true });
});
`);
