arq("ponte/src/auth/cofre.mjs", {"papel":"execucao","codificacao":"texto","bytes":1545,"sha256":"dd0658c88f50c52fea76186c40ddca150aaa67fc63d32957978d8b1b004aad72"}, String.raw`// Cofre do token GitHub. Só a ponte lê; nada aqui é serializado para HTTP.
import { mkdirSync, readFileSync, writeFileSync, rmSync, existsSync, chmodSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';

export function criarCofre({ persistir = 'memoria', dir = process.env.DIF_COFRE_DIR || join(homedir(), '.dif-ponte') } = {}) {
  const arquivo = join(dir, 'sessao.json');
  let atual = null; // { token, login, escopos, origem, host, criadoEm }

  if (persistir === 'arquivo' && existsSync(arquivo)) {
    try { atual = JSON.parse(readFileSync(arquivo, 'utf8')); } catch { atual = null; }
  }

  return {
    arquivo, persistir,
    /** Token para uso interno (cliente GitHub, provedor Copilot). Nunca enviar ao navegador. */
    obter: () => (atual ? atual.token : null),
    /** Metadados seguros para exibição. */
    info: () => (atual ? { login: atual.login, escopos: atual.escopos, origem: atual.origem, host: atual.host, criadoEm: atual.criadoEm } : null),
    guardar(dados) {
      atual = { ...dados, criadoEm: Date.now() };
      if (persistir === 'arquivo') {
        mkdirSync(dir, { recursive: true, mode: 0o700 });
        writeFileSync(arquivo, JSON.stringify(atual), { mode: 0o600 });
        try { chmodSync(arquivo, 0o600); } catch { /* Windows: permissões do perfil do usuário */ }
      }
    },
    atualizar(parcial) { if (atual) this.guardar({ ...atual, ...parcial }); },
    apagar() { atual = null; try { rmSync(arquivo, { force: true }); } catch { /* ok */ } },
  };
}
`);
