arq("ponte/src/auth/deteccao.mjs", {"papel":"execucao","codificacao":"texto","bytes":910,"sha256":"4ea883b672e999aa4d271ded5d228c2297e48d150138f9fd0745c58c0f70f0b0"}, String.raw`// Reaproveita um login GitHub já existente na máquina (opcional: DIF_GITHUB_USAR_LOGIN_EXISTENTE=1).
// Ordem: COPILOT_GITHUB_TOKEN, GH_TOKEN, GITHUB_TOKEN, depois ⟦CRASE⟧gh auth token⟦CRASE⟧ (só se o gh existir).
import { execFile } from 'node:child_process';

const execGh = host => new Promise(ok => {
  const args = ['auth', 'token'];
  if (host && host !== 'github.com') args.push('--hostname', host);
  execFile('gh', args, { timeout: 5000, windowsHide: true }, (erro, saida) => ok(erro ? null : String(saida).trim() || null));
});

export async function detectarLoginExistente({ env = process.env, host = 'github.com', usarGh = true } = {}) {
  for (const nome of ['COPILOT_GITHUB_TOKEN', 'GH_TOKEN', 'GITHUB_TOKEN']) {
    if (env[nome]) return { token: env[nome], origem: ⟦CRASE⟧variavel:⟦DOLAR_CHAVE⟧nome}⟦CRASE⟧ };
  }
  if (usarGh) { const t = await execGh(host); if (t) return { token: t, origem: 'gh-cli' }; }
  return null;
}
`);
