//@@ARQUIVO ponte/src/copilot/runtime.mjs | bytes=2594 | sha256=8860de542be7b245ed0cafb816e504133e8613ad0e2e175384d9f3917cf10819 | papel=execucao | codificacao=texto
arq("ponte/src/copilot/runtime.mjs", {"papel":"execucao","codificacao":"texto","bytes":2594,"sha256":"8860de542be7b245ed0cafb816e504133e8613ad0e2e175384d9f3917cf10819"}, String.raw`// Um único processo do runtime do Copilot por ponte, compartilhado pelo login SSO, pela leitura de
// repositórios (servidor MCP do GitHub embutido no runtime) e pelos agentes.
import { resolve, join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { mkdirSync } from 'node:fs';

export function criarRuntime(cfg, { sdk = null } = {}) {
  let modulo = sdk, cliente = null, chave = null, iniciando = null, util = null;

  async function carregarSdk() {
    if (modulo) return modulo;
    modulo = cfg.agentes.sdkModulo ? await import(pathToFileURL(resolve(cfg.agentes.sdkModulo)).href) : await import('@microsoft/copilot-sdk');
    return modulo;
  }

  const api = {
    carregarSdk,
    /** Cliente do runtime. Sem token = identidade do login SSO guardada pelo próprio runtime. */
    async cliente({ token = null } = {}) {
      const k = token ? ⟦CRASE⟧t:⟦DOLAR_CHAVE⟧token.slice(-6)}⟦CRASE⟧ : 'sso';
      if (cliente && chave === k) return cliente;
      if (iniciando && chave === k) return iniciando;
      if (cliente) { await cliente.stop().catch(() => {}); cliente = null; util = null; }
      chave = k;
      iniciando = (async () => {
        const { CopilotClient } = await carregarSdk();
        // o SDK repassa o token (se houver) ao processo filho; process.env global não é tocado
        const c = new CopilotClient({ mode: 'coding-agent', github: token ? { token, useLoggedInUser: false } : { useLoggedInUser: true }, clientInfo: { name: 'dif-ponte', version: '1.0.0' } });
        await c.start();
        cliente = c; iniciando = null;
        return c;
      })();
      try { return await iniciando; } catch (e) { iniciando = null; chave = null; throw e; }
    },
    /** Sessão de serviço (login e chamadas MCP): sem agente, sem permissões, pasta própria. */
    async sessaoUtilitaria() {
      if (util) return util;
      const c = await api.cliente();
      const dir = join(cfg.dados, 'runtime');
      mkdirSync(dir, { recursive: true });
      util = await c.createSession({ clientName: 'dif-ponte', workingDirectory: dir, permissions: { onRequest: () => ({ kind: 'reject', feedback: 'sessão de serviço da ponte' }) } });
      return util;
    },
    /** Esquece a sessão de serviço (ex.: depois de login/logout, para o MCP do GitHub recarregar a identidade). */
    async renovarSessao() { if (util) await util.disconnect().catch(() => {}); util = null; },
    async encerrar() { if (util) await util.disconnect().catch(() => {}); util = null; if (cliente) await cliente.stop().catch(() => {}); cliente = null; chave = null; },
  };
  return api;
}
`);
//@@FIM ponte/src/copilot/runtime.mjs

//@@ARQUIVO ponte/src/dados/contrato.mjs | bytes=2376 | sha256=9cabf31bc2bb7525dc776937cdc580cf45aeb9a4fda5725f1657802ab5277a7b | papel=execucao | codificacao=texto
arq("ponte/src/dados/contrato.mjs", {"papel":"execucao","codificacao":"texto","bytes":2376,"sha256":"9cabf31bc2bb7525dc776937cdc580cf45aeb9a4fda5725f1657802ab5277a7b"}, String.raw`// Contrato da camada de dados do DIF. Rotas e módulos falam SÓ com este contrato; o banco (SQLite hoje,
// Postgres amanhã) é um detalhe da implementação. Tudo é assíncrono, mesmo no SQLite (DECISOES D-40).
//
// /** @typedef {{ id:string, login:string, nome:string, cluster:string, papel:'admin'|'analista', ativo:boolean,
//  *   criado_em:string, atualizado_em:string, ultimo_login_em:string|null, tentativas_falhas:number,
//  *   bloqueado_ate:string|null, senha_temporaria:boolean, hash_senha?:string }} Usuario */
// /** @typedef {{ op:'salvar'|'excluir', tipo:string, id:string, descoberta_id?:string|null, json?:object,
//  *   versao_esperada:number }} OperacaoDocumento */
//
// Repositorio {
//   dialeto: 'sqlite' | 'postgres'
//   migrar(): Promise<{ aplicadas: number[] }>
//   transacao(fn: (repo) => Promise<T>): Promise<T>
//   usuarios: { criar(u), porId(id), porLogin(login), listar(), atualizar(id, campos), contar() }
//   sessoes:  { criar(s), obter(hashToken), tocar(id, quando), encerrar(id), encerrarDoUsuario(usuarioId, excetoId?), limparExpiradas(agora) }
//   documentos: { listar({ tipos? }), obter(tipo, id), aplicarLote(ops, usuario) → { versoes: { 'tipo:id': n } } | lança CONFLITO }
//   auditoria: { registrar(evento), listar({ usuario?, acao?, de?, ate?, limite?, cursor? }) → { itens, proximo } }
//   fechar(): Promise<void>
// }

export const TIPOS_DOCUMENTO = ['descoberta', 'conversa', 'backlog', 'fonte', 'meta'];

export class ErroConflito extends Error {
  constructor(conflitos) { super('Outra pessoa alterou estes dados.'); this.status = 409; this.codigo = 'CONFLITO'; this.conflitos = conflitos; }
}

/** Confere que um objeto cumpre o contrato (usado nos testes e ao abrir o banco). */
export function conferirContrato(repo) {
  const exigir = (obj, nomes, onde) => nomes.forEach(n => { if (typeof obj?.[n] !== 'function') throw new Error(⟦CRASE⟧repositório sem ⟦DOLAR_CHAVE⟧onde}.⟦DOLAR_CHAVE⟧n}()⟦CRASE⟧); });
  exigir(repo, ['migrar', 'transacao', 'fechar'], 'repo');
  exigir(repo.usuarios, ['criar', 'porId', 'porLogin', 'listar', 'atualizar', 'contar'], 'usuarios');
  exigir(repo.sessoes, ['criar', 'obter', 'tocar', 'encerrar', 'encerrarDoUsuario', 'limparExpiradas'], 'sessoes');
  exigir(repo.documentos, ['listar', 'obter', 'aplicarLote'], 'documentos');
  exigir(repo.auditoria, ['registrar', 'listar'], 'auditoria');
  return repo;
}
`);
//@@FIM ponte/src/dados/contrato.mjs

//@@ARQUIVO ponte/src/dados/index.mjs | bytes=495 | sha256=0d1b57e7d2016edfaac905d72c4d4015a44d2f31568336568469491b84ff5784 | papel=execucao | codificacao=texto
arq("ponte/src/dados/index.mjs", {"papel":"execucao","codificacao":"texto","bytes":495,"sha256":"0d1b57e7d2016edfaac905d72c4d4015a44d2f31568336568469491b84ff5784"}, String.raw`// Abre o repositório conforme a configuração (DIF_BD) e aplica as migrações.
import { join } from 'node:path';
import { abrirSqlite } from './sqlite.mjs';
import { abrirPostgres } from './postgres.mjs';

export async function abrirRepositorio(cfg) {
  const tipo = (cfg.bd && cfg.bd.tipo) || 'sqlite';
  const repo = tipo === 'postgres' ? await abrirPostgres(cfg.bd.url) : await abrirSqlite((cfg.bd && cfg.bd.arquivo) || join(cfg.dados, 'dif.db'));
  await repo.migrar();
  return repo;
}
`);
//@@FIM ponte/src/dados/index.mjs

//@@ARQUIVO ponte/src/dados/migracoes/001_inicial.sql | bytes=2646 | sha256=43e9a9d16aaef17234f054a56ba636ff7ac37c6ad3d67d4dbabf8df200545819 | papel=execucao | codificacao=texto
arq("ponte/src/dados/migracoes/001_inicial.sql", {"papel":"execucao","codificacao":"texto","bytes":2646,"sha256":"43e9a9d16aaef17234f054a56ba636ff7ac37c6ad3d67d4dbabf8df200545819"}, String.raw`-- 001 · esquema inicial do DIF (SQL portável: SQLite hoje, Postgres amanhã).
-- Convenções: ids TEXT (gerados pela aplicação), datas ISO-8601 em TEXT, JSON em TEXT, booleanos em INTEGER 0/1.
-- Equivalentes em Postgres (ver docs/DADOS.md): json → JSONB, *_em → TIMESTAMPTZ, ativo/… → BOOLEAN.

CREATE TABLE IF NOT EXISTS usuarios (
  id                TEXT PRIMARY KEY,
  login             TEXT NOT NULL UNIQUE,          -- sempre em minúsculas
  nome              TEXT NOT NULL,
  cluster           TEXT NOT NULL,
  papel             TEXT NOT NULL CHECK (papel IN ('admin', 'analista')),
  hash_senha        TEXT NOT NULL,                 -- scrypt$N$r$p$sal$hash
  ativo             INTEGER NOT NULL DEFAULT 1,
  senha_temporaria  INTEGER NOT NULL DEFAULT 0,
  criado_em         TEXT NOT NULL,
  atualizado_em     TEXT NOT NULL,
  ultimo_login_em   TEXT,
  tentativas_falhas INTEGER NOT NULL DEFAULT 0,
  bloqueado_ate     TEXT
);

CREATE TABLE IF NOT EXISTS sessoes_usuario (
  id             TEXT PRIMARY KEY,
  usuario_id     TEXT NOT NULL REFERENCES usuarios (id),
  hash_token     TEXT NOT NULL UNIQUE,             -- sha256 do token do cookie; o token em si nunca é gravado
  criado_em      TEXT NOT NULL,
  expira_em      TEXT NOT NULL,                    -- limite absoluto
  ultimo_uso_em  TEXT NOT NULL,                    -- para a expiração por inatividade
  agente_usuario TEXT
);
CREATE INDEX IF NOT EXISTS sessoes_usuario_usuario ON sessoes_usuario (usuario_id);

-- Armazém de documentos versionados (descoberta, conversa, backlog, fonte, meta).
CREATE TABLE IF NOT EXISTS documentos (
  tipo           TEXT NOT NULL,
  id             TEXT NOT NULL,
  descoberta_id  TEXT,
  json           TEXT NOT NULL,                    -- Postgres: JSONB
  versao         INTEGER NOT NULL,
  criado_por     TEXT REFERENCES usuarios (id),
  criado_em      TEXT NOT NULL,
  atualizado_por TEXT REFERENCES usuarios (id),
  atualizado_em  TEXT NOT NULL,
  excluido_em    TEXT,
  excluido_por   TEXT REFERENCES usuarios (id),
  PRIMARY KEY (tipo, id)
);
CREATE INDEX IF NOT EXISTS documentos_descoberta ON documentos (descoberta_id);

CREATE TABLE IF NOT EXISTS auditoria (
  id            TEXT PRIMARY KEY,
  quando        TEXT NOT NULL,
  usuario_id    TEXT,
  usuario_login TEXT,
  acao          TEXT NOT NULL,
  entidade      TEXT,
  entidade_id   TEXT,
  detalhes      TEXT,                              -- JSON redigido (sem tokens nem senhas)
  ip            TEXT
);
CREATE INDEX IF NOT EXISTS auditoria_quando ON auditoria (quando);
CREATE INDEX IF NOT EXISTS auditoria_usuario ON auditoria (usuario_login, quando);
`);
//@@FIM ponte/src/dados/migracoes/001_inicial.sql

//@@ARQUIVO ponte/src/dados/postgres.mjs | bytes=1038 | sha256=45247ecd85770c0e9e3cbd8b38a8584894b5f047c13ff3e9782f1684bd2afc1b | papel=execucao | codificacao=texto
arq("ponte/src/dados/postgres.mjs", {"papel":"execucao","codificacao":"texto","bytes":1038,"sha256":"45247ecd85770c0e9e3cbd8b38a8584894b5f047c13ff3e9782f1684bd2afc1b"}, String.raw`// Esqueleto do executor Postgres (servidor externo). NÃO implementado nesta versão — ver docs/DADOS.md.
// Para implementar sem tocar em rotas nem no front-end:
//   1. npm i pg (dependência só da ponte) e DIF_BD=postgres + DIF_BD_URL=postgres://usuario@host/banco (senha via variável/cofre).
//   2. Executor com Pool: todos/um/executar → pool.query(paraPostgres(sql), params); script → client.query(sql);
//      transacao → client dedicado com BEGIN/COMMIT/ROLLBACK (passando um executor ligado a esse client).
//   3. Devolver criarRepositorioSql(executor) com dialeto 'postgres' — as migrações em migracoes/*.sql já são portáveis.
//   4. Rodar o teste de contrato: DIF_BD_TESTE_PG_URL=postgres://… npm test.
// import { criarRepositorioSql, paraPostgres } from './sql.mjs';

export async function abrirPostgres(/* url */) {
  throw Object.assign(new Error('DIF_BD=postgres ainda não está implementado nesta versão (veja docs/DADOS.md › "Implementar o Postgres").'), { codigo: 'BD_NAO_IMPLEMENTADO' });
}
`);
//@@FIM ponte/src/dados/postgres.mjs

//@@ARQUIVO ponte/src/dados/rotas.mjs | bytes=4873 | sha256=e1b8688a3c5e98e85969a44589fa5242068ac7cd698a4a8cc6f60da07b5ea02e | papel=execucao | codificacao=texto
arq("ponte/src/dados/rotas.mjs", {"papel":"execucao","codificacao":"texto","bytes":4873,"sha256":"e1b8688a3c5e98e85969a44589fa5242068ac7cd698a4a8cc6f60da07b5ea02e"}, String.raw`// Rotas /api/dados/*: o estado do DIF (descobertas, conversas, backlogs, fontes, meta) como documentos versionados.
// O navegador salva POR DIFERENÇA, em lote atômico, com a versão que conhece (conflito → 409 e recarga).
import { TIPOS_DOCUMENTO } from './contrato.mjs';

const ID = /^[A-Za-z0-9._:-]{1,80}$/;
const LIMITE_LOTE = 20 * 1024 * 1024, MAX_OPS = 5000;
const erro = (status, msg, codigo) => Object.assign(new Error(msg), { status, codigo });

function validarOps(ops) {
  if (!Array.isArray(ops) || !ops.length) throw erro(400, 'lote vazio');
  if (ops.length > MAX_OPS) throw erro(400, ⟦CRASE⟧lote com mais de ⟦DOLAR_CHAVE⟧MAX_OPS} operações⟦CRASE⟧);
  return ops.map(o => {
    if (!o || !['salvar', 'excluir'].includes(o.op)) throw erro(400, 'operação inválida');
    if (!TIPOS_DOCUMENTO.includes(o.tipo)) throw erro(400, ⟦CRASE⟧tipo inválido: ⟦DOLAR_CHAVE⟧o.tipo}⟦CRASE⟧);
    if (!ID.test(String(o.id || ''))) throw erro(400, ⟦CRASE⟧id inválido: ⟦DOLAR_CHAVE⟧o.id}⟦CRASE⟧);
    if (o.descoberta_id != null && !ID.test(String(o.descoberta_id))) throw erro(400, 'descoberta_id inválido');
    if (!Number.isInteger(o.versao_esperada) || o.versao_esperada < 0) throw erro(400, 'versao_esperada inválida');
    if (o.op === 'salvar' && (!o.json || typeof o.json !== 'object' || Array.isArray(o.json))) throw erro(400, 'json do documento inválido');
    return { op: o.op, tipo: o.tipo, id: o.id, descoberta_id: o.descoberta_id ?? null, json: o.json, versao_esperada: o.versao_esperada };
  });
}

export function registrarDados(app) {
  const { repositorio: repo, auditoria } = app;

  app.rota('GET', '/api/dados', async (req, res, c) => {
    const documentos = await repo.documentos.listar();
    c.json(200, { documentos, vazio: !documentos.length });
  });

  app.rota('POST', '/api/dados/lote', async (req, res, c) => {
    const ops = validarOps(c.corpo.ops);
    const motivo = ['importacao', 'inicial'].includes(c.corpo.motivo) ? c.corpo.motivo : null;
    const r = await repo.documentos.aplicarLote(ops, c.usuario);
    if (motivo) auditoria.registrar(motivo === 'importacao' ? 'dados_importados' : 'dados_iniciais', { documentos: ops.length, tipos: contar(ops) });
    else for (const o of ops) {
      if (o.tipo === 'meta') continue; // contadores e ordem: sem valor para auditoria
      const acao = o.op === 'excluir' ? 'excluido' : r.versoes[⟦CRASE⟧⟦DOLAR_CHAVE⟧o.tipo}:⟦DOLAR_CHAVE⟧o.id}⟦CRASE⟧] === 1 || o.versao_esperada === 0 ? 'criado' : 'alterado';
      auditoria.registrar(⟦CRASE⟧⟦DOLAR_CHAVE⟧o.tipo}_⟦DOLAR_CHAVE⟧acao}⟦CRASE⟧, { entidade: o.tipo, entidade_id: o.id, ...(o.descoberta_id ? { descoberta: o.descoberta_id } : {}), versao: r.versoes[⟦CRASE⟧⟦DOLAR_CHAVE⟧o.tipo}:⟦DOLAR_CHAVE⟧o.id}⟦CRASE⟧] });
    }
    c.json(200, r);
  }, { limite: LIMITE_LOTE });

  /** Zerar a base: só admin, com a palavra ZERAR. Exclusão lógica de tudo + meta/geral vazio. */
  app.rota('POST', '/api/dados/zerar', async (req, res, c) => {
    if (c.corpo.confirmacao !== 'ZERAR') throw erro(400, 'Digite ZERAR para confirmar.', 'SEM_CONFIRMACAO');
    const meta = { versao: 1, seq: { d: 0, f: 0, m: 0 }, ordem: { descobertas: [], fontes: [] } };
    const r = await repo.transacao(async t => {
      const atuais = await t.documentos.listar();
      const ops = atuais.filter(d => !(d.tipo === 'meta' && d.id === 'geral')).map(d => ({ op: 'excluir', tipo: d.tipo, id: d.id, versao_esperada: d.versao }));
      const m = await t.documentos.obter('meta', 'geral');
      ops.push({ op: 'salvar', tipo: 'meta', id: 'geral', json: meta, versao_esperada: m && !m.excluido_em ? m.versao : 0 });
      return t.documentos.aplicarLote(ops, c.usuario);
    });
    auditoria.registrar('base_zerada', { documentos_excluidos: Object.keys(r.versoes).length - 1 });
    c.json(200, r);
  }, { papel: 'admin' });

  /** Restaurar a demonstração: só admin, com a palavra de confirmação. Exclui tudo e grava o estado enviado. */
  app.rota('POST', '/api/dados/restaurar', async (req, res, c) => {
    if (c.corpo.confirmacao !== 'RESTAURAR') throw erro(400, 'Digite RESTAURAR para confirmar.', 'SEM_CONFIRMACAO');
    const novos = validarOps((c.corpo.ops || []).map(o => ({ ...o, op: 'salvar', versao_esperada: 0 })));
    const r = await repo.transacao(async t => {
      const atuais = await t.documentos.listar();
      const ids = new Set(novos.map(o => ⟦CRASE⟧⟦DOLAR_CHAVE⟧o.tipo}:⟦DOLAR_CHAVE⟧o.id}⟦CRASE⟧));
      const ops = [
        ...atuais.filter(d => !ids.has(⟦CRASE⟧⟦DOLAR_CHAVE⟧d.tipo}:⟦DOLAR_CHAVE⟧d.id}⟦CRASE⟧)).map(d => ({ op: 'excluir', tipo: d.tipo, id: d.id, versao_esperada: d.versao })),
        ...novos.map(o => { const a = atuais.find(d => d.tipo === o.tipo && d.id === o.id); return { ...o, versao_esperada: a ? a.versao : 0 }; }),
      ];
      return t.documentos.aplicarLote(ops, c.usuario);
    });
    auditoria.registrar('demonstracao_restaurada', { documentos: novos.length });
    c.json(200, r);
  }, { limite: LIMITE_LOTE, papel: 'admin' });
}

const contar = ops => ops.reduce((m, o) => ({ ...m, [o.tipo]: (m[o.tipo] || 0) + 1 }), {});
`);
