          return linhas.map(r => ({ tipo: r.tipo, id: r.id, descoberta_id: r.descoberta_id || null, json: JSON.parse(r.json), versao: Number(r.versao),
            criado_em: r.criado_em, atualizado_em: r.atualizado_em,
            criado_por: r.criado_por_login ? { login: r.criado_por_login, nome: r.criado_por_nome } : null,
            atualizado_por: r.atualizado_por_login ? { login: r.atualizado_por_login, nome: r.atualizado_por_nome } : null }));
