arq("ponte/src/dados/sqlite.mjs", {"papel":"execucao","codificacao":"texto","bytes":2931,"sha256":"ecbef0e11c87dd85fdd66e08be5d30653bbb959d56df5f17a995e3c10dd3fbd6"}, String.raw`// Executor SQLite com o módulo NATIVO do Node (node:sqlite, sem dependência). DatabaseSync é síncrono:
// uma fila serializa o acesso para que uma transação nunca se misture com consultas de outra requisição.
import { mkdirSync, closeSync, openSync, existsSync, chmodSync } from 'node:fs';
import { dirname } from 'node:path';
import { AsyncLocalStorage } from 'node:async_hooks';
import { criarRepositorioSql } from './sql.mjs';

let silenciado = false;
/** O node:sqlite ainda emite ExperimentalWarning; silencia SÓ esse aviso (os demais continuam). */
function silenciarAvisoSqlite() {
  if (silenciado) return; silenciado = true;
  const original = process.emitWarning;
  process.emitWarning = function (aviso, ...resto) {
    const txt = typeof aviso === 'string' ? aviso : aviso && aviso.message;
    const tipo = typeof resto[0] === 'string' ? resto[0] : resto[0] && resto[0].type;
    if ((tipo === 'ExperimentalWarning' || (aviso && aviso.name === 'ExperimentalWarning')) && /SQLite/i.test(String(txt))) return;
    return original.call(this, aviso, ...resto);
  };
}

export async function abrirSqlite(arquivo) {
  silenciarAvisoSqlite();
  const { DatabaseSync } = await import('node:sqlite');
  if (arquivo !== ':memory:') {
    mkdirSync(dirname(arquivo), { recursive: true });
    if (!existsSync(arquivo)) closeSync(openSync(arquivo, 'a', 0o600));
    try { chmodSync(arquivo, 0o600); } catch { /* Windows */ }
  }
  const db = new DatabaseSync(arquivo);
  db.exec('PRAGMA journal_mode = WAL; PRAGMA foreign_keys = ON; PRAGMA busy_timeout = 5000;');

  // fila: cada operação (ou transação inteira) roda sozinha
  let fila = Promise.resolve();
  const dentroDaTransacao = new AsyncLocalStorage();
  const enfileirar = fn => {
    if (dentroDaTransacao.getStore()) return Promise.resolve().then(fn); // já é a dona da fila
    const r = fila.then(fn, fn);
    fila = r.then(() => {}, () => {});
    return r;
  };
  const conv = p => (p || []).map(v => (v === undefined ? null : typeof v === 'boolean' ? (v ? 1 : 0) : v));
  const base = {
    dialeto: 'sqlite',
    todos: (sql, p) => enfileirar(() => db.prepare(sql).all(...conv(p))),
    um: (sql, p) => enfileirar(() => db.prepare(sql).get(...conv(p)) || null),
    executar: (sql, p) => enfileirar(() => { const r = db.prepare(sql).run(...conv(p)); return { alteradas: Number(r.changes) }; }),
    script: sql => enfileirar(() => { db.exec(sql); }),
    transacao: fn => enfileirar(() => dentroDaTransacao.run(true, async () => {
      db.exec('BEGIN IMMEDIATE');
      const tx = { ...base, transacao: f => f(tx) }; // transação aninhada = a mesma
      try { const r = await fn(tx); db.exec('COMMIT'); return r; }
      catch (e) { try { db.exec('ROLLBACK'); } catch { /* já desfeita */ } throw e; }
    })),
    fechar: async () => { await fila; try { db.close(); } catch { /* já fechado */ } },
  };
  return criarRepositorioSql(base);
}
`);
