arq("ponte/src/github/agentes-repo.mjs", {"papel":"execucao","codificacao":"texto","bytes":1001,"sha256":"88c0ea252767a37964c4289b047061b4f969c0596fb3fbdc4e7acad5c30ef6f4"}, String.raw`// Baixa .github/agents/*.agent.md de um repositório para um cache local (usado pelo carregador de agentes).
import { mkdirSync, writeFileSync, existsSync, readdirSync } from 'node:fs';
import { join, basename } from 'node:path';

export async function baixarAgentesDoRepo(gh, { dono, repo, ref, dirCache }) {
  const commit = await gh.commit(dono, repo, ref || 'HEAD');
  const destino = join(dirCache, ⟦CRASE⟧⟦DOLAR_CHAVE⟧dono}__⟦DOLAR_CHAVE⟧repo}@⟦DOLAR_CHAVE⟧commit.slice(0, 12)}⟦CRASE⟧);
  if (existsSync(destino) && readdirSync(destino).length) return { destino, commit, arquivos: readdirSync(destino) };
  const { arquivos } = await gh.arvore(dono, repo, commit);
  const agentes = arquivos.filter(a => /^\.github\/agents\/[^/]+\.agent\.md$/.test(a.caminho) && a.tamanho < 256 * 1024);
  mkdirSync(destino, { recursive: true });
  for (const a of agentes) writeFileSync(join(destino, basename(a.caminho)), await gh.conteudo(dono, repo, a.caminho, commit));
  return { destino, commit, arquivos: agentes.map(a => basename(a.caminho)) };
}
`);
