arq("ponte/src/github/cliente.mjs", {"papel":"execucao","codificacao":"texto","bytes":3588,"sha256":"adc0da119aa7271281e9105f089f688c81c1d82d1b3700cd6db0c425473e6e83"}, String.raw`// Cliente GitHub da ponte (Octokit) com o token do cofre. Erros viram códigos amigáveis.
import { Octokit } from '@octokit/rest';

const erro = (msg, status, codigo) => Object.assign(new Error(msg), { status, codigo });

export function criarClienteGithub({ apiUrl, obterToken }) {
  const cliente = () => {
    const token = obterToken();
    if (!token) throw erro('Entre com GitHub para usar esta fonte.', 401, 'SEM_LOGIN');
    return new Octokit({ auth: token, baseUrl: apiUrl, userAgent: 'dif-ponte/1.0', request: { retries: 0 } });
  };

  /** Executa com 1 nova tentativa em 5xx e traduz 401/403/404. */
  async function chamar(fn) {
    for (let tentativa = 0; ; tentativa++) {
      try { return await fn(cliente()); }
      catch (e) {
        if (e.codigo) throw e;
        const st = e.status;
        if (st >= 500 && tentativa < 1) { await new Promise(ok => setTimeout(ok, 400)); continue; }
        if (st === 401) throw erro('O GitHub recusou o token (expirado ou revogado). Entre de novo.', 401, 'SEM_LOGIN');
        if (st === 403 && String(e.response?.headers?.['x-ratelimit-remaining']) === '0') throw erro('Limite de requisições do GitHub atingido. Tente mais tarde.', 429, 'LIMITE_GITHUB');
        if (st === 403) throw erro('Sem permissão para este repositório.', 403, 'SEM_PERMISSAO');
        if (st === 404) throw erro('Repositório, branch ou arquivo não encontrado (ou sem acesso).', 404, 'NAO_ENCONTRADO');
        throw erro(⟦CRASE⟧Falha ao falar com o GitHub (⟦DOLAR_CHAVE⟧st || e.message})⟦CRASE⟧, 502, 'GITHUB_INDISPONIVEL');
      }
    }
  }

  return {
    async repos(busca = '') {
      const todos = await chamar(o => o.paginate(o.rest.repos.listForAuthenticatedUser, { per_page: 100, sort: 'pushed' }, (r, done) => r.data));
      const q = busca.trim().toLowerCase();
      return todos.filter(r => !q || r.full_name.toLowerCase().includes(q)).slice(0, 200)
        .map(r => ({ nome: r.full_name, dono: r.owner.login, repo: r.name, privado: r.private, branchPadrao: r.default_branch, descricao: r.description || '', atualizadoEm: r.pushed_at }));
    },
    async branches(dono, repo) {
      const lista = await chamar(o => o.paginate(o.rest.repos.listBranches, { owner: dono, repo, per_page: 100 }));
      return lista.map(b => ({ nome: b.name, commit: b.commit.sha }));
    },
    async commit(dono, repo, ref) {
      const r = await chamar(o => o.rest.repos.getCommit({ owner: dono, repo, ref }));
      return r.data.sha;
    },
    async arvore(dono, repo, sha) {
      const r = await chamar(o => o.rest.git.getTree({ owner: dono, repo, tree_sha: sha, recursive: 'true' }));
      return { truncada: !!r.data.truncated, arquivos: r.data.tree.filter(t => t.type === 'blob').map(t => ({ caminho: t.path, tamanho: t.size || 0 })) };
    },
    async conteudo(dono, repo, caminho, ref) {
      const r = await chamar(o => o.rest.repos.getContent({ owner: dono, repo, path: caminho, ref }));
      if (Array.isArray(r.data) || r.data.type !== 'file') throw erro('Caminho não é um arquivo', 400, 'NAO_ARQUIVO');
      return Buffer.from(r.data.content, r.data.encoding === 'base64' ? 'base64' : 'utf8').toString('utf8');
    },
    async criarIssue(dono, repo, { titulo, corpo, rotulos }) {
      const r = await chamar(o => o.rest.issues.create({ owner: dono, repo, title: titulo, body: corpo, labels: rotulos }));
      return { numero: r.data.number, url: r.data.html_url };
    },
    async listarIssues(dono, repo) {
      return chamar(o => o.paginate(o.rest.issues.listForRepo, { owner: dono, repo, state: 'all', per_page: 100 }));
    },
  };
}
`);
