export const MAPA = process.env.DIF_MAPEAMENTO ? JSON.parse(readFileSync(process.env.DIF_MAPEAMENTO, 'utf8')) : MAPA_PADRAO;

export const snake = s => String(s).replace(/([a-z0-9])([A-Z])/g, '$1_$2').replace(/[-\s]+/g, '_').toLowerCase();
