arq("ponte/src/github/issues.mjs", {"papel":"execucao","codificacao":"texto","bytes":2329,"sha256":"d157807ef34a02142137c90e9229bb275ae34e44066b6c84cff988f49bb0134c"}, String.raw`// Exportação opcional do backlog como issues (DIF_EXPORTAR_ISSUES=1). Ação irreversível fora do app:
// a interface mostra a prévia e exige digitar o nome do repositório; aqui garantimos idempotência pelo marcador.
const marcador = (bl, id) => ⟦CRASE⟧⟦ABRE_COMENTARIO⟧ dif:⟦DOLAR_CHAVE⟧bl}:⟦DOLAR_CHAVE⟧id} -->⟦CRASE⟧;

export function planejarIssues(backlogId, b) {
  const itens = [];
  for (const e of b.epicos || []) {
    itens.push({ chave: e.id, tipo: 'epico', titulo: ⟦CRASE⟧[⟦DOLAR_CHAVE⟧e.id}] ⟦DOLAR_CHAVE⟧e.titulo}⟦CRASE⟧, rotulos: ['epico', 'dif'],
      corpo: [⟦CRASE⟧**Objetivo:** ⟦DOLAR_CHAVE⟧e.objetivo || '—'}⟦CRASE⟧, ⟦CRASE⟧**Valor de negócio:** ⟦DOLAR_CHAVE⟧e.valor_negocio || '—'}⟦CRASE⟧, '', ⟦CRASE⟧Fatos: ⟦DOLAR_CHAVE⟧(e.fatos || []).join(', ') || '—'}⟦CRASE⟧, '', ⟦CRASE⟧Backlog ⟦DOLAR_CHAVE⟧backlogId} · pacote v⟦DOLAR_CHAVE⟧b.pacote_versao} · gerado pelo Squad BRA - Upstream⟦CRASE⟧, marcador(backlogId, e.id)].join('\n') });
    for (const h of e.historias || []) {
      itens.push({ chave: h.id, pai: e.id, tipo: 'historia', titulo: ⟦CRASE⟧[⟦DOLAR_CHAVE⟧h.id}] ⟦DOLAR_CHAVE⟧h.titulo}⟦CRASE⟧, rotulos: ['historia', 'dif'],
        corpo: [⟦CRASE⟧**Como** ⟦DOLAR_CHAVE⟧h.como}, **quero** ⟦DOLAR_CHAVE⟧h.quero}, **para** ⟦DOLAR_CHAVE⟧h.para}.⟦CRASE⟧, '', '### Critérios de aceite',
          ...(h.criterios || []).map(c => ⟦CRASE⟧- **⟦DOLAR_CHAVE⟧c.id}** (⟦DOLAR_CHAVE⟧(c.fatos || []).join(', ')})\n\n\⟦CRASE⟧\⟦CRASE⟧\⟦CRASE⟧gherkin\n⟦DOLAR_CHAVE⟧c.gherkin}\n\⟦CRASE⟧\⟦CRASE⟧\⟦CRASE⟧⟦CRASE⟧),
          '', ⟦CRASE⟧Épico: {{EPICO:⟦DOLAR_CHAVE⟧e.id}}}⟦CRASE⟧, ⟦CRASE⟧Backlog ⟦DOLAR_CHAVE⟧backlogId} · pacote v⟦DOLAR_CHAVE⟧b.pacote_versao} · gerado pelo Squad BRA - Upstream⟦CRASE⟧, marcador(backlogId, h.id)].join('\n') });
    }
  }
  return itens;
}

export async function exportarIssues(gh, { dono, repo, backlogId, backlog }) {
  const plano = planejarIssues(backlogId, backlog);
  const existentes = await gh.listarIssues(dono, repo);
  const numeroPorChave = {};
  for (const i of existentes) { const m = String(i.body || '').match(new RegExp(⟦CRASE⟧⟦ABRE_COMENTARIO⟧ dif:⟦DOLAR_CHAVE⟧backlogId}:([^ ]+) -->⟦CRASE⟧)); if (m) numeroPorChave[m[1]] = i.number; }
  const criadas = [], puladas = [];
  for (const it of plano) {
    if (numeroPorChave[it.chave]) { puladas.push({ chave: it.chave, numero: numeroPorChave[it.chave] }); continue; }
    const corpo = it.corpo.replace(/\{\{EPICO:([^}]+)\}\}/, (m, id) => (numeroPorChave[id] ? ⟦CRASE⟧#⟦DOLAR_CHAVE⟧numeroPorChave[id]}⟦CRASE⟧ : id));
    const r = await gh.criarIssue(dono, repo, { titulo: it.titulo, corpo, rotulos: it.rotulos });
    numeroPorChave[it.chave] = r.numero;
    criadas.push({ chave: it.chave, numero: r.numero, url: r.url });
  }
  return { criadas, puladas };
}
`);
