import { join } from 'node:path';
import { abrirSSE } from '../sse.mjs';
import { criarAuthGithub } from '../auth/github-auth.mjs';
import { criarAuthSso } from '../auth/sso-copilot.mjs';
import { criarRuntime } from '../copilot/runtime.mjs';
import { criarClienteGithub } from './cliente.mjs';
import { criarAcessoMcp } from './acesso-mcp.mjs';
