import { criarPonte } from './servidor.mjs';
import { abrirRepositorio } from './dados/index.mjs';
import { registrarGithub } from './github/rotas.mjs';
import { registrarAgentes } from './agentes/rotas.mjs';
import { registrarCopilot } from './copilot/rotas.mjs';
import { registrarPacotes } from './pacotes/rotas.mjs';
import { registrarContas } from './contas/rotas.mjs';
import { registrarDados } from './dados/rotas.mjs';
import { registrarUpstream } from './fontes/upstream.mjs';

/** @param {object} [deps] injeções para testes: { provedor, sdk } */
export async function montarPonte(cfg, extras = {}, deps = {}) {
  const repositorio = deps.repositorio || extras.repositorio || await abrirRepositorio(cfg);
  const ponte = criarPonte(cfg, { ...extras, repositorio, manterRepositorio: !!deps.repositorio });
  registrarContas(ponte.app);
  registrarDados(ponte.app);
  registrarUpstream(ponte.app);
  registrarGithub(ponte.app, deps);
  registrarCopilot(ponte.app, deps);
  registrarPacotes(ponte.app);
  registrarAgentes(ponte.app, deps);
  return ponte;
}
