arq("ponte/src/sse.mjs", {"papel":"execucao","codificacao":"texto","bytes":944,"sha256":"fa135de0b873119db19c71f5685e486ff75ed9b1bdb38c2c82beaf6b3b7276e3"}, String.raw`// Respostas text/event-stream com heartbeat e detecção de desconexão.
export function abrirSSE(req, res, { heartbeatMs = 15_000 } = {}) {
  res.writeHead(200, {
    'Content-Type': 'text/event-stream; charset=utf-8',
    'Cache-Control': 'no-store, no-transform',
    Connection: 'keep-alive',
    'X-Accel-Buffering': 'no',
  });
  res.flushHeaders?.();
  const controle = new AbortController();
  let aberto = true;
  const fechar = () => { if (!aberto) return; aberto = false; clearInterval(hb); controle.abort(); };
  const hb = setInterval(() => { if (aberto) res.write(': ping\n\n'); }, heartbeatMs);
  res.on('close', fechar);
  return {
    sinal: controle.signal,
    get aberto() { return aberto; },
    enviar(evento, dados) {
      if (!aberto) return false;
      res.write(⟦CRASE⟧event: ⟦DOLAR_CHAVE⟧evento}\ndata: ⟦DOLAR_CHAVE⟧JSON.stringify(dados ?? {})}\n\n⟦CRASE⟧);
      return true;
    },
    encerrar() { if (aberto) { fechar(); res.end(); } },
  };
}
`);
