  assert.equal(decidirPermissao({ kind: 'read', path: 'contexto.md' }, ws).decisao, 'aprovada');
  assert.equal(decidirPermissao({ kind: 'read', path: join(ws, '..', 'segredo') }, ws).decisao, 'negada');
  assert.equal(decidirPermissao({ kind: 'read', path: '/etc/passwd' }, ws).decisao, 'negada');
