test('chat (auto): simulado antes de ativar; Copilot com o modelo padrão depois; troca de modelo no meio da conversa', async () => {
  const p = await subirComGithub(SSO);
  try {
    await logarSso(p);
    let ev = await lerSSE(await p.api('/api/chat', { method: 'POST', body: await corpo() }));
    assert.equal(ev.find(x => x.evento === 'inicio').dados.provedor, 'falso', 'antes da ativação: agente simulado');
    assert.match((await json(await p.api('/api/saude'))).copilot.motivo, /não ativado/);

    await p.api('/api/copilot/ativar', { method: 'POST', body: JSON.stringify({ modelo_padrao: 'modelo-rapido-ficticio' }) });
    const conversa = 'c-troca-' + Date.now();
    ev = await lerSSE(await p.api('/api/chat', { method: 'POST', body: await corpo({ conversa }) }));
    assert.equal(ev.find(x => x.evento === 'inicio').dados.provedor, 'copilot');
    assert.deepEqual(ev.find(x => x.evento === 'modelo').dados, { id: 'modelo-rapido-ficticio', raciocinio: null, alterado: false });
    assert.match(ev.filter(x => x.evento === 'delta').map(x => x.dados.texto).join(''), /\[modelo: modelo-rapido-ficticio\]/);
    assert.equal(ev.find(x => x.evento === 'backlog').dados.validacao.ok, true);

    ev = await lerSSE(await p.api('/api/chat', { method: 'POST', body: await corpo({ conversa, modelo: 'modelo-raciocinio-ficticio', raciocinio: 'high' }) }));
    assert.deepEqual(ev.find(x => x.evento === 'modelo').dados, { id: 'modelo-raciocinio-ficticio', raciocinio: 'high', alterado: true });
    assert.match(ev.filter(x => x.evento === 'delta').map(x => x.dados.texto).join(''), /\[modelo: modelo-raciocinio-ficticio · high\]/);

    ev = await lerSSE(await p.api('/api/chat', { method: 'POST', body: await corpo({ conversa, modelo: 'modelo-bloqueado-ficticio' }) }));
    assert.equal(ev.find(x => x.evento === 'erro').dados.codigo, 'MODELO_INDISPONIVEL');
    assert.equal((await p.api('/api/chat', { method: 'POST', body: await corpo({ modelo: 'x y' }) })).status, 400);

    await p.api('/api/copilot/desativar', { method: 'POST' });
    ev = await lerSSE(await p.api('/api/chat', { method: 'POST', body: await corpo() }));
    assert.equal(ev.find(x => x.evento === 'inicio').dados.provedor, 'falso', 'desativado volta ao simulado');
  } finally { await p.parar(); }
});

