  const l = validarLevantamento({ modo: 'linha', fontes: FONTES, candidatas: [{ id: 'R-1', enunciado: 'E', evidencias: [{ fonteId: 'F-01', arquivo: 'a' }] }, { id: 'R-2', enunciado: 'fora', evidencias: [{ fonteId: 'F-99' }] }] });
