//@@ARQUIVO ponte/test/pacotes.test.mjs | bytes=9382 | sha256=e05a895f9f744bd9cf3e61a6c82a102a35278f6fc609925a4a25e4c70d810e11 | papel=repositorio | codificacao=texto
arq("ponte/test/pacotes.test.mjs", {"papel":"repositorio","codificacao":"texto","bytes":9382,"sha256":"e05a895f9f744bd9cf3e61a6c82a102a35278f6fc609925a4a25e4c70d810e11"}, String.raw`// Pacotes .zip de agentes, skills e hooks: leitor com proteções, prévia, importação e uso na sessão do Copilot (FALSO).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync, mkdtempSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { execFileSync } from 'node:child_process';
import { lerZip, caminhoSeguro } from '../src/pacotes/zip.mjs';
import { analisarPacote, lerHook } from '../src/pacotes/pacote.mjs';
import { escreverZip, pacoteFicticio } from '../../ferramentas/zip-escrever.mjs';
import { __registro } from '../../ferramentas/fake-copilot-sdk.mjs';
import { subirComGithub, lerSSE, logarSso } from './apoio.mjs';
import { contextoDe } from '../../test/contexto-seed.mjs';

const md = (n, d = 'x') => ⟦CRASE⟧---\nname: ⟦DOLAR_CHAVE⟧n}\ndescription: ⟦DOLAR_CHAVE⟧d}\n---\ncorpo\n⟦CRASE⟧;
const recusa = (buf, re, lim) => assert.throws(() => lerZip(buf, lim), e => re.test(e.message), String(re));

test('leitor: pacote fictício e zip gerado pelo utilitário zip do sistema', () => {
  const e = lerZip(pacoteFicticio());
  assert.equal(e.length, 6);
  assert.match(e.find(x => x.nome.endsWith('SKILL.md')).dados.toString(), /name: checar-gherkin/);
  let zipCli = null; try { execFileSync('zip', ['-v'], { stdio: 'ignore' }); zipCli = true; } catch { zipCli = false; }
  if (zipCli) {
    const d = mkdtempSync(join(tmpdir(), 'dif-zipcli-'));
    execFileSync('mkdir', ['-p', join(d, 'p', 'agents')]);
    writeFileSync(join(d, 'p', 'agents', 'a.agent.md'), md('a'));
    execFileSync('zip', ['-qr', 'p.zip', 'p'], { cwd: d });
    assert.deepEqual(lerZip(readFileSync(join(d, 'p.zip'))).map(x => x.nome), ['p/agents/a.agent.md']);
  }
});

test('leitor: proteções (zip slip, absolutos, links, bomba, limites, CRC, criptografia)', () => {
  for (const nome of ['../fora.md', 'a/../../fora.md', '/etc/x.md', 'C:/x.md', 'a\\b.md', 'a//b.md', './a.md']) recusa(escreverZip([{ nome, dados: 'x' }]), /caminho|não é aceito/);
  assert.equal(caminhoSeguro('a/b/c.md'), 'a/b/c.md');
  recusa(escreverZip([{ nome: 'link.md', dados: '/etc/passwd', modoUnix: 0o120777 }]), /link simbólico/);
  recusa(escreverZip([{ nome: 'dev.md', dados: '', modoUnix: 0o020644 }]), /especial/);
  recusa(escreverZip([{ nome: 'bomba.txt', dados: Buffer.alloc(8 * 1024 * 1024) }]), /zip bomb/);
  recusa(escreverZip([{ nome: 'a.md', dados: 'abc', tamanhoDeclarado: 2 }]), /tamanho declarado|descompactar/);
  recusa(escreverZip([{ nome: 'a.md', dados: 'abc', flags: 1 }]), /criptografada/);
  recusa(escreverZip(Array.from({ length: 6 }, (_, i) => ({ nome: ⟦CRASE⟧⟦DOLAR_CHAVE⟧i}.md⟦CRASE⟧, dados: 'x' }))), /entradas/, { compactado: 1e6, descompactado: 1e6, entradas: 5, razao: 100 });
  recusa(escreverZip([{ nome: 'a.md', dados: 'x'.repeat(2000) }]), /descompactado/, { compactado: 1e6, descompactado: 1000, entradas: 10, razao: 100 });
  recusa(Buffer.alloc(30 * 1024 * 1024), /maior que 20 MB/);
  recusa(Buffer.from('não é zip nenhum, só texto para o teste ............'), /não é um .zip/);
  const z = escreverZip([{ nome: 'a.md', dados: 'conteudo', metodo: 0 }]);
  z[30 + 4 + 2] ^= 0xff; // corrompe um byte dos dados
  recusa(z, /CRC/);
  recusa(escreverZip([{ nome: 'A.md', dados: '1' }, { nome: 'a.md', dados: '2' }]), /repetida/);
});

test('análise: extensões, front matter, hooks, colisões e normalização de .github/', () => {
  const a = analisarPacote(escreverZip([
    { nome: '.github/agents/x.agent.md', dados: md('x') },
    { nome: 'skills/s1/SKILL.md', dados: md('s1', 'uma skill') },
    { nome: 'skills/s2/apoio.md', dados: 'sem SKILL.md' },
    { nome: 'skills/s3/SKILL.md', dados: '---\nname: s3\n---\ncorpo' },
    { nome: 'hooks/h.json', dados: JSON.stringify({ hooks: { preToolUse: [{ type: 'command', bash: 'echo 1' }] } }) },
    { nome: 'hooks/ruim.json', dados: '{"x":1}' },
    { nome: 'scripts/rodar.sh', dados: 'rm -rf /' },
    { nome: 'LEIA.md', dados: 'oi' },
  ]), { agentesExistentes: ['x'], skillsExistentes: [] });
  assert.equal(a.ok, false);
  assert.deepEqual(a.agentes.map(x => x.nome), ['x']);
  assert.deepEqual(a.skills.map(x => x.nome), ['s1']);
  assert.deepEqual(a.hooks.map(x => x.eventos), [['preToolUse']]);
  assert.ok(a.erros.some(e => /rodar\.sh: tipo de arquivo não permitido/.test(e)));
  assert.ok(a.erros.some(e => /skills\/s2: falta SKILL\.md/.test(e)));
  assert.ok(a.erros.some(e => /s3.*description é obrigatória/.test(e)));
  assert.ok(a.erros.some(e => /ruim\.json/.test(e)));
  assert.ok(a.avisos.some(e => /"x" já existe/.test(e)));
  assert.ok(a.avisos.some(e => /LEIA\.md: ignorado/.test(e)));
  assert.ok(a.arquivos.some(f => f.destino === 'agents/x.agent.md'));
  assert.throws(() => lerHook('{"hooks":{"x y":[]}}'), /evento inválido/);
  const b = analisarPacote(pacoteFicticio(), { skillsExistentes: ['checar-gherkin'] });
  assert.ok(b.erros.some(e => /já existe em outro pacote/.test(e)));
});

test('API: prévia sem gravar, importação, uso na sessão do Copilot, hooks com confirmação e remoção', async () => {
  const p = await subirComGithub({ DIF_GITHUB_LOGIN: 'sso', DIF_GITHUB_CLIENT_ID: '', DIF_PROVEDOR: 'auto' });
  const zip = pacoteFicticio();
  const enviar = (caminho, corpo = zip, tipo = 'application/zip') => p.api(caminho, { method: 'POST', body: corpo, headers: { 'content-type': tipo } });
  try {
    assert.equal((await enviar('/api/pacotes/previa', zip, 'text/plain')).status, 415);
    const prev = await (await enviar('/api/pacotes/previa')).json();
    assert.equal(prev.ok, true);
    assert.deepEqual([prev.manifesto.nome, prev.agentes.length, prev.skills.length, prev.hooks.length], ['pacote-ficticio', 1, 2, 1]);
    assert.match(prev.hooks[0].conteudo, /sessionStart/);
    assert.equal(existsSync(join(p.dados, 'pacotes')), false, 'prévia não grava nada');
    const mau = await enviar('/api/pacotes', escreverZip([{ nome: '../x.md', dados: 'x' }]));
    assert.equal(mau.status, 400); assert.match((await mau.json()).erro, /caminho/);

    let r = await enviar('/api/pacotes');
    assert.equal(r.status, 201);
    const { pacote } = await r.json();
    assert.match(pacote.id, /^PK-[a-f0-9]{10}$/);
    assert.equal(pacote.hooks[0].ligado, false, 'hooks entram desligados');
    assert.ok(existsSync(join(p.dados, 'pacotes', pacote.id, 'skills', 'checar-gherkin', 'SKILL.md')));
    assert.equal((await enviar('/api/pacotes')).status, 409);
    const ag = await (await p.api('/api/agentes')).json();
    assert.equal(ag.agentes.find(a => a.nome === 'analista-garantias').origem, 'pacote:pacote-ficticio');

    await logarSso(p);
    await p.api('/api/copilot/ativar', { method: 'POST', body: JSON.stringify({ modelo_padrao: 'modelo-rapido-ficticio' }) });
    let cat = await (await p.api('/api/chat/catalogo')).json();
    assert.deepEqual(cat.skills.filter(s => s.origem.startsWith('pacote:')).map(s => s.nome), ['checar-gherkin', 'glossario-garantias']);

    const ctx = await contextoDe('D-001', 1);
    const turno = async extra => lerSSE(await p.api('/api/chat', { method: 'POST', body: JSON.stringify({ conversa: 'c-pk-' + Date.now() + Math.random().toString(36).slice(2, 5), agente: 'analista-garantias', contexto: ctx, mensagens: [{ papel: 'usuario', texto: 'Proponha épicos e histórias' }], ...extra }) }));
    let ev = await turno({ skill: 'checar-gherkin' });
    assert.match(ev.filter(x => x.evento === 'delta').map(x => x.dados.texto).join(''), /\[skill: checar-gherkin\]/);
    let cfgSessao = __registro.sessoes.at(-1).cfg;
    assert.deepEqual(cfgSessao.skills.directories, [join(p.dados, 'pacotes', pacote.id, 'skills')]);
    assert.deepEqual(cfgSessao.hooks, { enableRepositoryHooks: false }, 'hook desligado não vai para o runtime');
    assert.equal(cfgSessao.agents.selected, 'analista-garantias');

    r = await p.api(⟦CRASE⟧/api/pacotes/⟦DOLAR_CHAVE⟧pacote.id}⟦CRASE⟧, { method: 'PATCH', body: JSON.stringify({ hooks: { 'registrar-sessao': { ligado: true } } }) });
    assert.equal(r.status, 400); assert.equal((await r.json()).codigo, 'HOOK_SEM_CONFIRMACAO');
    r = await p.api(⟦CRASE⟧/api/pacotes/⟦DOLAR_CHAVE⟧pacote.id}⟦CRASE⟧, { method: 'PATCH', body: JSON.stringify({ hooks: { 'registrar-sessao': { ligado: true, confirmacao: pacote.hooks[0].hash } }, skills: { 'glossario-garantias': false } }) });
    assert.equal(r.status, 200);
    ev = await turno({});
    cfgSessao = __registro.sessoes.at(-1).cfg;
    const dirHooks = join(p.dados, 'pacotes', pacote.id, 'hooks-ligados');
    assert.deepEqual(cfgSessao.hooks, { enableRepositoryHooks: false, directories: [dirHooks] });
    assert.ok(existsSync(join(dirHooks, 'registrar-sessao.json')));
    assert.deepEqual(cfgSessao.skills.disabledSkills, ['glossario-garantias']);
    cat = await (await p.api('/api/chat/catalogo')).json();
    assert.ok(!cat.skills.some(s => s.nome === 'glossario-garantias'), 'skill desligada sai do menu "/"');

    r = await p.api(⟦CRASE⟧/api/pacotes/⟦DOLAR_CHAVE⟧pacote.id}⟦CRASE⟧, { method: 'DELETE' });
    assert.equal(r.status, 200);
    assert.equal(existsSync(join(p.dados, 'pacotes', pacote.id)), false);
    assert.ok(!(await (await p.api('/api/agentes')).json()).agentes.some(a => a.nome === 'analista-garantias'));
    assert.deepEqual((await (await p.api('/api/pacotes')).json()).pacotes, []);
    assert.equal((await p.api('/api/pacotes/../../x', { method: 'DELETE' })).status, 404);
  } finally { await p.parar(); }
});
`);
