test('redação remove tokens de texto e de objetos', () => {
  const t = 'gho_ABCDEFGHIJKLMNOP1234 e github_pat_11ABCDEFGHIJ_xyz e Bearer abc.def.ghi1234';
  const r = redigir(t);
  assert.doesNotMatch(r, /gho_ABC|github_pat_11|abc\.def/);
  const o = redigir({ access_token: 'gho_ZZZZZZZZZZZZZZZZ', ok: 1 });
  assert.equal(o.ok, 1);
  assert.doesNotMatch(JSON.stringify(o), /ZZZZ/);
});

