//@@ARQUIVO ponte/test/sso.test.mjs | bytes=4745 | sha256=0c80a9dd933d33a1ecb79fe7733df9452f09fbe21f7ce36617bf7549db172e7e | papel=repositorio | codificacao=texto
arq("ponte/test/sso.test.mjs", {"papel":"repositorio","codificacao":"texto","bytes":4745,"sha256":"0c80a9dd933d33a1ecb79fe7733df9452f09fbe21f7ce36617bf7549db172e7e"}, String.raw`// Login SSO pelo runtime do Copilot (sem client id/secret), repositórios via MCP do runtime e agentes — tudo FALSO.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { subirComGithub, lerSSE, logarSso } from './apoio.mjs';
import { contextoDe } from '../../test/contexto-seed.mjs';

const SSO = { DIF_GITHUB_LOGIN: 'sso', DIF_GITHUB_CLIENT_ID: '' };

test('SSO: sem client id, abre a URL do runtime, autoriza e conecta; token nunca aparece', async () => {
  const p = await subirComGithub(SSO);
  try {
    let e = await (await p.api('/api/auth/github/estado')).json();
    assert.equal(e.modo, 'sso');
    const ini = await (await p.api('/api/auth/github/iniciar', { method: 'POST' })).json();
    assert.equal(ini.estado, 'pendente');
    assert.match(ini.url, /\/login\/oauth\/authorize\?client_id=fake-copilot-cli&redirect_uri=http%3A%2F%2F127\.0\.0\.1/);
    e = await logarSso(p);
    assert.equal(e.estado, 'conectado');
    assert.equal(e.login, 'analista-ficticio');
    const saude = await (await p.api('/api/saude')).json();
    assert.equal(saude.github.conectado, true);
    assert.equal(saude.github.modo, 'sso');
    assert.doesNotMatch(JSON.stringify([ini, e, saude]) + (await p.ponte.app.auditoria.texto()), /gho_/);
  } finally { await p.parar(); }
});

test('SSO: cancelar no GitHub vira "negado"; sair desconecta', async () => {
  const p = await subirComGithub(SSO);
  try {
    let e = await logarSso(p, { negar: true });
    assert.equal(e.estado, 'negado');
    e = await logarSso(p);
    assert.equal(e.estado, 'conectado');
    e = await (await p.api('/api/auth/github/sair', { method: 'POST' })).json();
    assert.equal(e.estado, 'desconectado');
    assert.equal((await p.api('/api/github/repos')).status, 401);
  } finally { await p.parar(); }
});

test('SSO: consentimento para guardar o login (sistemas sem chaveiro)', async () => {
  process.env.FAKE_SSO_CONSENT = '1';
  const p = await subirComGithub(SSO);
  try {
    let e = await logarSso(p);
    assert.equal(e.estado, 'consentimento');
    e = await (await p.api('/api/auth/github/consentir', { method: 'POST', body: JSON.stringify({ permitir: true }) })).json();
    for (let i = 0; i < 40 && e.estado !== 'conectado'; i++) { await new Promise(ok => setTimeout(ok, 50)); e = await (await p.api('/api/auth/github/estado')).json(); }
    assert.equal(e.estado, 'conectado');
  } finally { delete process.env.FAKE_SSO_CONSENT; await p.parar(); }
});

test('SSO: Fonte GitHub lê repositórios pelo MCP do runtime e extrai as mesmas regras', async () => {
  const p = await subirComGithub(SSO);
  try {
    await logarSso(p);
    const repos = (await (await p.api('/api/github/repos?busca=garantias')).json()).repos;
    assert.deepEqual(repos.map(x => x.nome), ['dif-ficticio/garantias-demo']);
    const br = (await (await p.api('/api/github/repos/dif-ficticio/garantias-demo/branches')).json()).branches;
    assert.deepEqual(br.map(b => b.nome), ['main', 'develop']);
    const r = await p.api('/api/github/extrair', { method: 'POST', body: JSON.stringify({ dono: 'dif-ficticio', repo: 'garantias-demo', ref: 'main', fonte: { id: 'F-10', nome: 'garantias-demo' } }) });
    const ev = await lerSSE(r);
    const fim = ev.find(x => x.evento === 'fim').dados;
    assert.equal(fim.totais.arquivos, 5);
    assert.equal(fim.totais.conflitos, 1);
    const ag = await (await p.api('/api/github/agentes', { method: 'POST', body: JSON.stringify({ dono: 'dif-ficticio', repo: 'garantias-demo', ref: 'main' }) })).json();
    assert.deepEqual(ag.arquivos, ['po-garantias.agent.md']);
  } finally { await p.parar(); }
});

test('SSO: agentes no provedor Copilot usam a identidade do login (sem token na ponte)', async () => {
  const p = await subirComGithub({ ...SSO, DIF_PROVEDOR: 'copilot' });
  try {
    const corpo = async () => JSON.stringify({ conversa: 'c-' + Date.now(), agente: 'po-epicos', contexto: await contextoDe('D-001', 1), mensagens: [{ papel: 'usuario', texto: 'Proponha épicos e histórias' }] });
    let ev = await lerSSE(await p.api('/api/chat', { method: 'POST', body: await corpo() }));
    assert.equal(ev.find(x => x.evento === 'erro').dados.codigo, 'SEM_LOGIN', 'antes do login');
    await logarSso(p);
    ev = await lerSSE(await p.api('/api/chat', { method: 'POST', body: await corpo() }));
    assert.equal(ev.find(x => x.evento === 'inicio').dados.provedor, 'copilot');
    assert.ok(ev.some(x => x.evento === 'permissao' && x.dados.decisao === 'negada'), 'shell negado');
    const b = ev.find(x => x.evento === 'backlog').dados;
    assert.equal(b.validacao.ok, true);
    assert.equal(b.validacao.cobertura, 1);
  } finally { await p.parar(); }
});
`);
