//@@ARQUIVO test/compartilhado.test.mjs | bytes=2826 | sha256=63ebccf8621d2cc4b07f88966b99477d89be7d4feff2dd328ee59182aea7074c | papel=repositorio | codificacao=texto
arq("test/compartilhado.test.mjs", {"papel":"repositorio","codificacao":"texto","bytes":2826,"sha256":"63ebccf8621d2cc4b07f88966b99477d89be7d4feff2dd328ee59182aea7074c"}, String.raw`import { test } from 'node:test';
import assert from 'node:assert/strict';
import { validarBacklog, pedidoDeCorrecao } from '../compartilhado/backlog-schema.mjs';
import { extrairBacklog } from '../compartilhado/extrair-backlog.mjs';
import { gerarBacklogDemo, respostaDemo } from '../compartilhado/backlog-demo.mjs';
import { contextoDe } from './contexto-seed.mjs';

test('gerador demo cobre 100% dos fatos e passa na validação para as versões do seed', async () => {
  const ctx = await contextoDe('D-001', 1);
  assert.ok(ctx.pacotes.length >= 2);
  const b = gerarBacklogDemo(ctx, { agente: 'po-epicos' });
  const v = validarBacklog(b, ctx);
  assert.deepEqual(v.erros, []);
  assert.equal(v.cobertura, 1);
  assert.ok(v.totais.historias >= 4);
});

test('validação acusa cada tipo de erro com mensagem legível', async () => {
  const ctx = await contextoDe('D-001', 1);
  const b = gerarBacklogDemo(ctx);
  const h = b.epicos[0].historias[0];
  h.criterios[0].fatos = ['FN-R-9999'];
  h.criterios.push({ id: 'CA-1', gherkin: 'sem formato', fatos: [] });
  h.dependencias = ['HI-99.9'];
  b.epicos[0].historias.push({ ...b.epicos[0].historias[1], id: h.id });
  delete b.epicos[1].historias[0].como;
  const v = validarBacklog(b, ctx);
  const t = v.erros.join('\n');
  assert.equal(v.ok, false);
  assert.match(t, new RegExp(⟦CRASE⟧⟦DOLAR_CHAVE⟧h.id} · CA-1 cita FN-R-9999, que não existe na v1⟦CRASE⟧));
  assert.match(t, /id repetido na história/);
  assert.match(t, /não cita nenhum fato/);
  assert.match(t, /depende de HI-99\.9/);
  assert.match(t, /Id repetido/);
  assert.match(t, /sem "como"/);
  assert.ok(v.avisos.some(a => /Gherkin sem Dado/.test(a)));
  assert.match(pedidoDeCorrecao(v, ctx), /^Erros de validação/);
});

test('estrutura inválida não quebra o validador', () => {
  for (const x of [null, 1, 'x', [], {}, { esquema: 'dif-backlog/1', epicos: [null, 3] }]) {
    const v = validarBacklog(x, { versao: { n: 1 }, pacotes: [] });
    assert.equal(v.ok, false);
  }
});

test('extrai o último bloco dif-backlog, tolera vírgula sobrando e detecta bloco pendente', () => {
  const um = '⟦CRASE⟧⟦CRASE⟧⟦CRASE⟧dif-backlog\n{"a":1}\n⟦CRASE⟧⟦CRASE⟧⟦CRASE⟧';
  const dois = 'texto\n⟦CRASE⟧⟦CRASE⟧⟦CRASE⟧dif-backlog\n{"esquema":"dif-backlog/1","epicos":[1,2,],}\n⟦CRASE⟧⟦CRASE⟧⟦CRASE⟧\nfim';
  assert.deepEqual(extrairBacklog(um + '\n' + dois).backlog, { esquema: 'dif-backlog/1', epicos: [1, 2] });
  assert.equal(extrairBacklog('⟦CRASE⟧⟦CRASE⟧⟦CRASE⟧dif-backlog\n{"a":').pendente, true);
  assert.match(extrairBacklog('⟦CRASE⟧⟦CRASE⟧⟦CRASE⟧dif-backlog\n{nada}\n⟦CRASE⟧⟦CRASE⟧⟦CRASE⟧').erroDeParse, /JSON inválido/);
  assert.equal(extrairBacklog('sem bloco').backlog, null);
});

test('respostaDemo contém um bloco válido', async () => {
  const ctx = await contextoDe('D-001', 1);
  const b = gerarBacklogDemo(ctx);
  const x = extrairBacklog(respostaDemo(ctx, b));
  assert.equal(JSON.stringify(x.backlog), JSON.stringify(b));
});
`);
