arq("test/dois-arquivos.test.mjs", {"papel":"repositorio","codificacao":"texto","bytes":5151,"sha256":"c19b7fcfc102391fe74a75b81c101e98dd35e39fe11938db911c4bbea2f1430c"}, String.raw`// Versão em dois arquivos (squad-bra-2arquivos/1): ida e volta byte a byte e ponte subindo só com os dois arquivos.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync, copyFileSync, existsSync, readdirSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { spawn, spawnSync, execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { gerarDoisArquivos, codificar } from '../ferramentas/dois-arquivos.mjs';

const raiz = join(dirname(fileURLToPath(import.meta.url)), '..');
let gerado = null;
const gerar = async () => (gerado ||= await gerarDoisArquivos({ saida: mkdtempSync(join(tmpdir(), 'sb-2arq-')) }));
const pasta = r => { const d = mkdtempSync(join(tmpdir(), 'sb-2arq-pc-')); copyFileSync(r.arqApp, join(d, 'squad-bra-app.html')); copyFileSync(r.arqPonte, join(d, 'squad-bra-ponte.mjs')); return d; };

test('escape é reversível (crase, ⟦DOLAR_CHAVE⟧, ⟦LT_BARRA⟧script, ⟦ABRE_COMENTARIO⟧, ⟦ABRE⟧ e barra final)', async () => {
  // o lançador é um fragmento (roda ao ser importado): pega só a função decodificar do texto dele
  const fonte = readFileSync(join(raiz, 'ferramentas', 'dois-arquivos-lancador.mjs'), 'utf8').match(/export function decodificar[\s\S]*?\n}\n/)[0].replace('export ', '');
  const decodificar = new Function(⟦CRASE⟧⟦DOLAR_CHAVE⟧fonte}; return decodificar;⟦CRASE⟧)();
  const casos = ['a ⟦CRASE⟧b⟦CRASE⟧ ⟦DOLAR_CHAVE⟧c} ⟦LT_BARRA⟧script> ⟦LT_BARRA⟧SCRIPT x ⟦ABRE_COMENTARIO⟧ d --> ⟦ABRE⟧CRASE⟧ ⟦ABRE⟧ABRE⟧ fim\\', '\\', ''];
  for (const c of casos) {
    const e = codificar(c);
    assert.ok(!/⟦CRASE⟧|\$\{|<\/script|⟦ABRE_COMENTARIO⟧/i.test(e), e);
    assert.equal(decodificar(e, 'texto').toString('utf8'), c);
  }
});

test('ida e volta: --extrair reconstrói o repositório byte a byte e --verificar confere', async () => {
  const r = await gerar(), d = pasta(r);
  assert.equal(spawnSync(process.execPath, ['squad-bra-ponte.mjs', '--verificar'], { cwd: d, encoding: 'utf8' }).status, 0);
  const x = spawnSync(process.execPath, ['squad-bra-ponte.mjs', '--extrair', 'rep'], { cwd: d, encoding: 'utf8' });
  assert.equal(x.status, 0, x.stderr);
  const lista = execFileSync('git', ['ls-files', '--cached', '--others', '--exclude-standard'], { cwd: raiz, encoding: 'utf8' }).split('\n').filter(p => p && !p.startsWith('e2e/capturas/'));
  for (const p of lista) assert.ok(readFileSync(join(d, 'rep', p)).equals(readFileSync(join(raiz, p))), p);
  assert.ok(!existsSync(join(d, 'rep', 'node_modules')), 'dependências geradas não voltam para o repositório');
  // pasta não vazia é recusada sem --forcar
  assert.notEqual(spawnSync(process.execPath, ['squad-bra-ponte.mjs', '--extrair', 'rep'], { cwd: d }).status, 0);
  // a aplicação começa e termina como o HTML original (fontes e aviso ficam em blocos marcados)
  const app = readFileSync(r.arqApp, 'utf8'), orig = readFileSync(join(raiz, 'DIF-Descoberta-Regras.html'), 'utf8');
  assert.ok(app.startsWith(orig.slice(0, orig.indexOf('\n'))) && app.endsWith(orig.slice(orig.lastIndexOf('</body>'))));
  assert.ok(app.includes('data-squad-arquivo="chat/src/ChatApp.tsx"'));
});

test('ponte sobe de uma pasta limpa só com os dois arquivos (sem npm), serve o HTML e a API', async () => {
  const r = await gerar(), d = pasta(r);
  const filho = spawn(process.execPath, ['squad-bra-ponte.mjs'], { cwd: d, env: { PATH: process.env.PATH, HOME: d, DIF_PONTE_PORTA: '0', DIF_ABRIR_NAVEGADOR: '0' }, stdio: ['ignore', 'pipe', 'pipe'] });
  try {
    const porta = await new Promise((ok, erro) => {
      let saida = '';
      const t = setTimeout(() => erro(new Error('a ponte não subiu: ' + saida)), 20000);
      filho.stdout.on('data', b => { saida += b; const m = saida.match(/127\.0\.0\.1:(\d+)/); if (m) { clearTimeout(t); ok(+m[1]); } });
      filho.stderr.on('data', b => { saida += b; });
      filho.on('exit', c => { clearTimeout(t); erro(new Error(⟦CRASE⟧saiu com ⟦DOLAR_CHAVE⟧c}: ⟦DOLAR_CHAVE⟧saida}⟦CRASE⟧)); });
    });
    const base = ⟦CRASE⟧http://127.0.0.1:⟦DOLAR_CHAVE⟧porta}⟦CRASE⟧;
    const res = await fetch(base + '/'), html = await res.text();
    assert.match(html, /name="dif-ponte" content="1"/);
    const cookie = res.headers.get('set-cookie').split(';')[0], csrf = html.match(/name="dif-csrf" content="([^"]+)"/)[1];
    const h = extra => ({ cookie: extra ? ⟦CRASE⟧⟦DOLAR_CHAVE⟧cookie}; ⟦DOLAR_CHAVE⟧extra}⟦CRASE⟧ : cookie, 'x-dif-csrf': csrf, 'content-type': 'application/json' });
    assert.equal((await (await fetch(base + '/api/saude', { headers: h() })).json()).provedor, 'falso');
    const cad = await fetch(base + '/api/conta/cadastro', { method: 'POST', headers: h(), body: JSON.stringify({ nome: 'Admin do PC', login: 'admin.pc', cluster: 'Garantias', senha: 'senha-do-pc-1234' }) });
    assert.equal(cad.status, 201);
    const ag = await (await fetch(base + '/api/agentes', { headers: h(cad.headers.get('set-cookie').split(';')[0]) })).json();
    assert.ok(ag.agentes.some(a => a.nome === 'po-epicos'), 'agentes padrão (yaml empacotado funciona)');
    assert.ok(existsSync(join(d, '.dados', 'dif.db')) && existsSync(join(d, '.env')));
    assert.equal(readdirSync(join(d, '.squad-bra')).filter(n => n.startsWith('ponte-')).length, 1);
  } finally { filho.kill('SIGTERM'); }
});
`);
